import{_ as n,o,c as g,a2 as s}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Continuous-Distributions.md","filePath":"manual-zh/Continuous-Distributions.md","lastUpdated":1785684581000}'),m={name:"manual-zh/Continuous-Distributions.md"};function e(r,t,_,a,p,F){return o(),g("div",null,[...t[0]||(t[0]=[s('<h4 id="_7-7-10-1-连续分布" tabindex="-1">7.7.10.1 连续分布 <a class="header-anchor" href="#_7-7-10-1-连续分布" aria-label="Permalink to &quot;7.7.10.1 连续分布&quot;">​</a></h4><p>以下是可用的连续分布：</p><p>Function: __<strong>PDF.BETA</strong> <em>( x)</em> Function: __<strong>CDF.BETA</strong> <em>( x, a, b)</em> Function: __<strong>IDF.BETA</strong> <em>( p, a, b)</em> Function: __<strong>RV.BETA</strong> <em>( a, b)</em> Function: __<strong>NPDF.BETA</strong> <em>( x, a, b, lambda)</em> Function: __<strong>NCDF.BETA</strong> <em>( x, a, b, lambda)</em></p><p>形状参数为 a 和 b 的 Beta 分布。非中心分布额外接受一个参数 lambda。约束：a &gt; 0，b &gt; 0，lambda &gt;= 0，0 &lt;= x &lt;= 1，0 &lt;= p &lt;= 1。</p><p>Function: __<strong>PDF.BVNOR</strong> <em>( x0, x1, rho)</em> Function: __<strong>CDF.BVNOR</strong> <em>( x0, x1, rho)</em></p><p>两个标准正态变量、相关系数为 rho 的二元正态分布。必须提供两个变量 x0 和 x1。约束：0 &lt;= rho &lt;= 1，0 &lt;= p &lt;= 1。</p><p>Function: __<strong>PDF.CAUCHY</strong> <em>( x, a, b)</em> Function: __<strong>CDF.CAUCHY</strong> <em>( x, a, b)</em> Function: __<strong>IDF.CAUCHY</strong> <em>( p, a, b)</em> Function: __<strong>RV.CAUCHY</strong> <em>( a, b)</em></p><p>位置参数为 a、尺度参数为 b 的柯西分布。约束：b &gt; 0，0 &lt; p &lt; 1。</p><p>Function: __<strong>CDF.CHISQ</strong> <em>( x, df)</em> Function: __<strong>SIG.CHISQ</strong> <em>( x, df)</em> Function: __<strong>IDF.CHISQ</strong> <em>( p, df)</em> Function: __<strong>RV.CHISQ</strong> <em>( df)</em> Function: __<strong>NCDF.CHISQ</strong> <em>( x, df, lambda)</em></p><p>自由度为 df 的卡方分布。非中心分布额外接受一个参数 lambda。约束：df &gt; 0，lambda &gt; 0，x &gt;= 0，0 &lt;= p &lt; 1。</p><p>Function: __<strong>PDF.EXP</strong> <em>( x, a)</em> Function: __<strong>CDF.EXP</strong> <em>( x, a)</em> Function: __<strong>IDF.EXP</strong> <em>( p, a)</em> Function: __<strong>RV.EXP</strong> <em>( a)</em></p><p>尺度参数为 a 的指数分布。a 的倒数表示衰减率。约束：a &gt; 0，x &gt;= 0，0 &lt;= p &lt; 1。</p><p>Function: __<strong>PDF.XPOWER</strong> <em>( x, a, b)</em> Function: __<strong>RV.XPOWER</strong> <em>( a, b)</em></p><p>尺度参数 a 为正、幂参数 b 非负的指数幂分布。约束：a &gt; 0，b &gt;= 0，x &gt;= 0，0 &lt;= p &lt;= 1。此分布为 PSPP 扩展。</p><p>Function: __<strong>PDF.F</strong> <em>( x, df1, df2)</em> Function: __<strong>CDF.F</strong> <em>( x, df1, df2)</em> Function: __<strong>SIG.F</strong> <em>( x, df1, df2)</em> Function: __<strong>IDF.F</strong> <em>( p, df1, df2)</em> Function: __<strong>RV.F</strong> <em>( df1, df2)</em></p><p>两个自由度为 df1 和 df2 的卡方偏离量的 F 分布。非中心分布额外接受一个参数 lambda。约束：df1 &gt; 0，df2 &gt; 0，lambda &gt;= 0，x &gt;= 0，0 &lt;= p &lt; 1。</p><p>Function: __<strong>PDF.GAMMA</strong> <em>( x, a, b)</em> Function: __<strong>CDF.GAMMA</strong> <em>( x, a, b)</em> Function: __<strong>IDF.GAMMA</strong> <em>( p, a, b)</em> Function: __<strong>RV.GAMMA</strong> <em>( a, b)</em></p><p>形状参数为 a、尺度参数为 b 的伽马分布。约束：a &gt; 0，b &gt; 0，x &gt;= 0，0 &lt;= p &lt; 1。</p><p>Function: __<strong>PDF.LANDAU</strong> <em>( x)</em> Function: __<strong>RV.LANDAU</strong> <em>()</em></p><p>朗道分布。</p><p>Function: __<strong>PDF.LAPLACE</strong> <em>( x, a, b)</em> Function: __<strong>CDF.LAPLACE</strong> <em>( x, a, b)</em> Function: __<strong>IDF.LAPLACE</strong> <em>( p, a, b)</em> Function: __<strong>RV.LAPLACE</strong> <em>( a, b)</em></p><p>位置参数为 a、尺度参数为 b 的拉普拉斯分布。约束：b &gt; 0，0 &lt; p &lt; 1。</p><p>Function: __<strong>RV.LEVY</strong> <em>( c, alpha)</em></p><p>尺度为 c、指数为 alpha 的列维对称 α-稳定分布。约束：0 &lt; alpha &lt;= 2。</p><p>Function: __<strong>RV.LVSKEW</strong> <em>( c, alpha, beta)</em></p><p>尺度为 c、指数为 alpha、偏度为参数 beta 的列维偏斜 α-稳定分布。约束：0 &lt; alpha &lt;= 2，-1 &lt;= beta &lt;= 1。</p><p>Function: __<strong>PDF.LOGISTIC</strong> <em>( x, a, b)</em> Function: __<strong>CDF.LOGISTIC</strong> <em>( x, a, b)</em> Function: __<strong>IDF.LOGISTIC</strong> <em>( p, a, b)</em> Function: __<strong>RV.LOGISTIC</strong> <em>( a, b)</em></p><p>位置参数为 a、尺度参数为 b 的逻辑斯谛分布。约束：b &gt; 0，0 &lt; p &lt; 1。</p><p>Function: __<strong>PDF.LNORMAL</strong> <em>( x, a, b)</em> Function: __<strong>CDF.LNORMAL</strong> <em>( x, a, b)</em> Function: __<strong>IDF.LNORMAL</strong> <em>( p, a, b)</em> Function: __<strong>RV.LNORMAL</strong> <em>( a, b)</em></p><p>参数为 a 和 b 的对数正态分布。约束：a &gt; 0，b &gt; 0，x &gt;= 0，0 &lt;= p &lt; 1。</p><p>Function: __<strong>PDF.NORMAL</strong> <em>( x, mu, sigma)</em> Function: __<strong>CDF.NORMAL</strong> <em>( x, mu, sigma)</em> Function: __<strong>IDF.NORMAL</strong> <em>( p, mu, sigma)</em> Function: __<strong>RV.NORMAL</strong> <em>( mu, sigma)</em></p><p>均值为 mu、标准差为 sigma 的正态分布。约束：b &gt; 0，0 &lt; p &lt; 1。另有三个函数可用作简写：</p><p>Function: __<strong>CDFNORM</strong> <em>( x)</em></p><p>等价于 CDF.NORMAL(x, 0, 1)。</p><p>Function: __<strong>PROBIT</strong> <em>( p)</em></p><p>等价于 IDF.NORMAL(p, 0, 1)。</p><p>Function: __<strong>NORMAL</strong> <em>( sigma)</em></p><p>等价于 RV.NORMAL(0, sigma)。</p><p>Function: __<strong>PDF.NTAIL</strong> <em>( x, a, sigma)</em> Function: __<strong>RV.NTAIL</strong> <em>( a, sigma)</em></p><p>下界为 a、标准差为 sigma 的正态尾分布。此分布为 PSPP 扩展。约束：a &gt; 0，x &gt; a，0 &lt; p &lt; 1。</p><p>Function: __<strong>PDF.PARETO</strong> <em>( x, a, b)</em> Function: __<strong>CDF.PARETO</strong> <em>( x, a, b)</em> Function: __<strong>IDF.PARETO</strong> <em>( p, a, b)</em> Function: __<strong>RV.PARETO</strong> <em>( a, b)</em></p><p>阈值为参数 a、形状为参数 b 的帕累托分布。约束：a &gt; 0，b &gt; 0，x &gt;= a，0 &lt;= p &lt; 1。</p><p>Function: __<strong>PDF.RAYLEIGH</strong> <em>( x, sigma)</em> Function: __<strong>CDF.RAYLEIGH</strong> <em>( x, sigma)</em> Function: __<strong>IDF.RAYLEIGH</strong> <em>( p, sigma)</em> Function: __<strong>RV.RAYLEIGH</strong> <em>( sigma)</em></p><p>尺度参数为 sigma 的瑞利分布。此分布为 PSPP 扩展。约束：sigma &gt; 0，x &gt; 0。</p><p>Function: __<strong>PDF.RTAIL</strong> <em>( x, a, sigma)</em> Function: __<strong>RV.RTAIL</strong> <em>( a, sigma)</em></p><p>下界为 a、尺度参数为 sigma 的瑞利尾分布。此分布为 PSPP 扩展。约束：a &gt; 0，sigma &gt; 0，x &gt; a。</p><p>Function: __<strong>PDF.T</strong> <em>( x, df)</em> Function: __<strong>CDF.T</strong> <em>( x, df)</em> Function: __<strong>IDF.T</strong> <em>( p, df)</em> Function: __<strong>RV.T</strong> <em>( df)</em></p><p>自由度为 df 的 t 分布。非中心分布额外接受一个参数 lambda。约束：df &gt; 0，0 &lt; p &lt; 1。</p><p>Function: __<strong>PDF.T1G</strong> <em>( x, a, b)</em> Function: __<strong>CDF.T1G</strong> <em>( x, a, b)</em> Function: __<strong>IDF.T1G</strong> <em>( p, a, b)</em></p><p>参数为 a 和 b 的 I 型冈贝尔分布。此分布为 PSPP 扩展。约束：0 &lt; p &lt; 1。</p><p>Function: __<strong>PDF.T2G</strong> <em>( x, a, b)</em> Function: __<strong>CDF.T2G</strong> <em>( x, a, b)</em> Function: __<strong>IDF.T2G</strong> <em>( p, a, b)</em></p><p>参数为 a 和 b 的 II 型冈贝尔分布。此分布为 PSPP 扩展。约束：x &gt; 0，0 &lt; p &lt; 1。</p><p>Function: __<strong>PDF.UNIFORM</strong> <em>( x, a, b)</em> Function: __<strong>CDF.UNIFORM</strong> <em>( x, a, b)</em> Function: __<strong>IDF.UNIFORM</strong> <em>( p, a, b)</em> Function: __<strong>RV.UNIFORM</strong> <em>( a, b)</em></p><p>参数为 a 和 b 的均匀分布。约束：a &lt;= x &lt;= b，0 &lt;= p &lt;= 1。另有函数可用作简写：</p><p>Function: __<strong>UNIFORM</strong> <em>( b)</em></p><p>等价于 RV.UNIFORM(0, b)。</p><p>Function: __<strong>PDF.WEIBULL</strong> <em>( x, a, b)</em> Function: __<strong>CDF.WEIBULL</strong> <em>( x, a, b)</em> Function: __<strong>IDF.WEIBULL</strong> <em>( p, a, b)</em> Function: __<strong>RV.WEIBULL</strong> <em>( a, b)</em></p><p>参数为 a 和 b 的威布尔分布。约束：a &gt; 0，b &gt; 0，x &gt;= 0，0 &lt;= p &lt; 1。</p>',58)])])}const c=n(m,[["render",e]]);export{u as __pageData,c as default};
